}

.brand-mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid rgba(255, 90, 22, 0.55);
  color: var(--ember-hot);
  font-family: var(--display);
  font-size: 20px;
  line-height: 1;
  transform: rotate(-6deg);
  background: rgba(15, 7, 6, 0.54);
  box-shadow: inset 0 0 16px rgba(255, 77, 15, 0.1);
}

.objective {
  padding-left: 18px;
  border-left: 1px solid var(--line);
}

.eyebrow,
.status-label {
  display: block;
  color: rgba(241, 230, 210, 0.42);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.2em;
}

.objective strong {
  display: block;
  margin-top: 5px;
  color: var(--bone);
  font-family: var(--body);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.wave-chip {
  position: absolute;
  top: max(24px, env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 31px;
  padding: 0 15px;
  color: rgba(241, 230, 210, 0.62);
  border: 1px solid rgba(241, 230, 210, 0.13);
  background: linear-gradient(180deg, rgba(21, 11, 11, 0.78), rgba(9, 6, 7, 0.58));
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.17em;
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}

.wave-chip i {
  width: 3px;
  height: 3px;
  background: var(--ember);
  border-radius: 50%;
  box-shadow: 0 0 7px var(--ember);
}

#hostile-count { color: var(--ember-hot); }

.minimap-shell {
  position: absolute;
  top: max(20px, env(safe-area-inset-top));
  right: max(26px, env(safe-area-inset-right));
  width: 174px;
}

.minimap-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
  color: rgba(241, 230, 210, 0.34);
  font-size: 7px;
  letter-spacing: 0.15em;
}

.minimap-label b { color: rgba(255, 90, 22, 0.72); font-weight: 700; }

.minimap-frame {
  position: relative;
  width: 174px;
  height: 174px;
  padding: 7px;
  background: rgba(7, 5, 6, 0.66);
  border: 1px solid rgba(241, 230, 210, 0.14);
  clip-path: polygon(11px 0, 100% 0, 100% calc(100% - 11px), calc(100% - 11px) 100%, 0 100%, 0 11px);
  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.24);
}

.minimap-frame::before,
.minimap-frame::after {
  content: "";
  position: absolute;
  background: var(--ember);
  opacity: 0.66;
}

.minimap-frame::before { width: 1px; height: 14px; right: 10px; top: 9px; }
.minimap-frame::after { width: 14px; height: 1px; right: 9px; top: 10px; }

#minimap {
  display: block;
  width: 100%;
  height: 100%;
  opacity: 0.9;
}

.north {
  position: absolute;
  top: 10px;
  left: 50%;
  transform: translateX(-50%);
  color: rgba(241, 230, 210, 0.36);
  font-size: 7px;
}

/* Crosshair */

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 34px;
  height: 34px;
  transform: translate(-50%, -50%);
  opacity: 0.82;
}

.crosshair i {
  position: absolute;
  background: var(--bone);
  box-shadow: 0 0 4px rgba(255, 162, 57, 0.6);
}

.ch-top, .ch-bottom { left: 50%; width: 1px; height: 7px; transform: translateX(-50%); }
.ch-left, .ch-right { top: 50%; height: 1px; width: 7px; transform: translateY(-50%); }
.ch-top { top: 3px; }
.ch-bottom { bottom: 3px; }
.ch-left { left: 3px; }
.ch-right { right: 3px; }

.ch-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 3px;
  transform: translate(-50%, -50%);
  background: var(--ember-hot);
  border-radius: 50%;
  box-shadow: 0 0 7px var(--ember);
}

.hitmarker {
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: scale(0.6);
  transition: opacity 80ms ease, transform 90ms ease;
}

.hitmarker.is-hit {
  opacity: 1;
  transform: scale(1);
}

.hitmarker i {
  width: 6px;
  height: 1px;
  background: #fff4db;
  box-shadow: 0 0 5px #ff8b31;
}
.hitmarker i:nth-child(1) { left: 1px; top: 8px; transform: rotate(45deg); }
.hitmarker i:nth-child(2) { right: 1px; top: 8px; transform: rotate(-45deg); }
.hitmarker i:nth-child(3) { left: 1px; bottom: 8px; transform: rotate(-45deg); }
.hitmarker i:nth-child(4) { right: 1px; bottom: 8px; transform: rotate(45deg); }

/* Announcement + toasts */

.announcement {
  position: absolute;
  top: 21%;
  left: 50%;
  width: min(500px, 80vw);
  text-align: center;
  transform: translate(-50%, -8px);
  opacity: 0;
  transition: opacity 220ms ease, transform 260ms ease;
}

.announcement.is-visible { opacity: 1; transform: translate(-50%, 0); }

.ann-kicker {
  display: block;
  margin-bottom: 8px;
  color: var(--ember);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.36em;
}

.ann-title {
  display: block;
  color: var(--bone);
  font-family: var(--display);
  font-size: clamp(34px, 6vw, 66px);
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: -0.04em;
  text-shadow: 0 2px 0 #2d0a05, 0 0 35px rgba(255, 69, 12, 0.25);
}

.toast-stack {
  position: absolute;
  left: max(26px, env(safe-area-inset-left));
  bottom: 126px;
  display: flex;
  flex-direction: column-reverse;
  gap: 5px;
  width: 280px;
}

.toast {
  display: flex;
  align-items: center;
  gap: 9px;
  color: rgba(241, 230, 210, 0.7);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  animation: toast-in 160ms ease-out both;
}

.toast::before {
  content: "";
  width: 16px;
  height: 1px;
  background: var(--ember);
  box-shadow: 0 0 7px rgba(255, 90, 22, 0.7);
}

.toast.is-leaving { animation: toast-out 300ms ease-in both; }

@keyframes toast-in {
  from { opacity: 0; transform: translateX(-8px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes toast-out {
  to { opacity: 0; transform: translateX(-6px); }
}

/* Bottom status bar */

.statusbar {
  position: absolute;
  right: max(26px, env(safe-area-inset-right));
  bottom: max(18px, env(safe-area-inset-bottom));
  left: max(26px, env(safe-area-inset-left));
  display: grid;
  grid-template-columns: 1fr minmax(300px, 1.2fr) 1fr;
  align-items: end;
  gap: 28px;
  padding-top: 14px;
  border-top: 1px solid rgba(241, 230, 210, 0.12);
}

.statusbar::before {
  content: "";
  position: absolute;
  top: -1px;
  left: 0;
  width: 72px;
  height: 1px;
  background: var(--ember);
  box-shadow: 0 0 11px rgba(255, 90, 22, 0.65);
}

.vital-row { display: flex; align-items: center; gap: 14px; margin-top: 3px; }

#health-value {
  min-width: 84px;
  color: var(--bone);
  font-family: var(--display);
  font-size: 54px;
  line-height: 0.9;
  letter-spacing: -0.07em;
  text-shadow: 0 0 18px rgba(255, 90, 22, 0.12);
}

#health-value.is-low { color: #ff5e3a; animation: low-pulse 800ms ease-in-out infinite alternate; }

@keyframes low-pulse { to { opacity: 0.62; text-shadow: 0 0 22px rgba(255, 27, 12, 0.42); } }

.vital-copy { flex: 1; min-width: 96px; }

.vital-copy > span, .heat > span {
  color: rgba(241, 230, 210, 0.42);
  font-size: 7px;
  letter-spacing: 0.14em;
}

.meter {
  position: relative;
  height: 4px;
  margin-top: 7px;
  overflow: hidden;
  background: rgba(241, 230, 210, 0.1);
}

.meter i {
  display: block;
  width: 100%;
  height: 100%;
  transform-origin: left;
  background: linear-gradient(90deg, #8f1f12, var(--ember) 55%, var(--ember-hot));
  box-shadow: 0 0 10px rgba(255, 80, 20, 0.44);
  transition: transform 120ms linear;
}

.weapon-status { padding-bottom: 2px; }

.weapon-line {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 6px;
}

.weapon-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  color: var(--ember-hot);
  border: 1px solid rgba(255, 90, 22, 0.32);
  font-size: 25px;
  line-height: 1;
  background: rgba(255, 73, 13, 0.04);
  transform: rotate(45deg);
}

.weapon-icon::first-letter { transform: rotate(-45deg); }

.heat { flex: 1; }

.heat-meter { height: 3px; }
.heat-meter i { background: linear-gradient(90deg, #ff8b28, #fff0a8); }

.ammo {
  color: var(--bone);
  font-family: var(--display);
  font-size: 31px;
  line-height: 0.8;
}

.score-status { text-align: right; }

.score-line {
  display: flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 4px;
  margin-top: 2px;
}

.score-line b {
  color: var(--bone);
  font-family: var(--display);
  font-size: 34px;
  line-height: 0.9;
  letter-spacing: -0.05em;
}

.score-line span { color: rgba(241, 230, 210, 0.3); font-size: 10px; }

.score-total {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 5px;
  color: rgba(241, 230, 210, 0.35);
  font-size: 7px;
  letter-spacing: 0.14em;
}

.score-total b { color: var(--ember); font-weight: 700; }

.lock-hint {
  position: absolute;
  bottom: 101px;
  left: 50%;
  transform: translateX(-50%);
  color: rgba(241, 230, 210, 0.38);
  font-size: 8px;
  letter-spacing: 0.16em;
  white-space: nowrap;
  transition: opacity 400ms ease;
}

.lock-hint span { color: var(--ember); }
.lock-hint.is-hidden { display: block !important; opacity: 0; }

/* ------------------------------------------------------------------ */
/* Touch controls                                                      */
/* ------------------------------------------------------------------ */

.touch-ui { display: none; }

.joystick {
  position: absolute;
  left: max(20px, env(safe-area-inset-left));
  bottom: max(24px, env(safe-area-inset-bottom));
  width: 112px;
  height: 112px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(20, 12, 11, 0.2) 0 42%, rgba(12, 8, 8, 0.62) 43% 100%);
  border: 1px solid rgba(241, 230, 210, 0.2);
  pointer-events: auto;
  touch-action: none;
}

.joystick-ring {
  position: absolute;
  inset: 16px;
  border: 1px dashed rgba(241, 230, 210, 0.16);
  border-radius: 50%;
}

.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 46px;
  height: 46px;
  margin: -23px 0 0 -23px;
  border-radius: 50%;
  border: 1px solid rgba(255, 90, 22, 0.5);
  background: radial-gradient(circle at 38% 34%, rgba(255, 170, 66, 0.45), rgba(107, 24, 11, 0.68) 60%, rgba(22, 9, 8, 0.85));
  box-shadow: 0 0 20px rgba(255, 69, 12, 0.18);
  transition: transform 50ms linear;
}

.joystick > span {
  position: absolute;
  bottom: 10px;
  left: 50%;
  transform: translateX(-50%);
  color: rgba(241, 230, 210, 0.35);
  font-size: 7px;
  letter-spacing: 0.18em;
}

.fire-button {
  position: absolute;
  right: max(24px, env(safe-area-inset-right));
  bottom: max(26px, env(safe-area-inset-bottom));
  display: grid;
  place-items: center;
  align-content: center;
  gap: 1px;
  width: 94px;
  height: 94px;
  padding: 0;
  color: #170906;
  border: 0;
  border-radius: 50%;
  background:
    radial-gradient(circle at 38% 30%, #ffd976, #ff7b1f 44%, #a92b10 76%, #64160d);
  box-shadow: 0 0 0 1px rgba(255, 189, 91, 0.55), 0 0 32px rgba(255, 69, 12, 0.34), inset 0 -9px 15px rgba(74, 9, 4, 0.46);
  pointer-events: auto;
  touch-action: none;
}

.fire-button:active, .fire-button.is-firing {
  transform: scale(0.94);
  filter: brightness(1.25);
}

.fire-glyph { font-size: 26px; line-height: 1; }
.fire-button > span:last-child { font-family: var(--mono); font-size: 8px; font-weight: 700; letter-spacing: 0.18em; }

.look-zone {
  position: absolute;
  right: 0;
  top: 20%;
  bottom: 20%;
  width: 62%;
  pointer-events: auto;
  touch-action: none;
}

.look-zone span {
  position: absolute;
  right: 26px;
  top: 48%;
  color: rgba(241, 230, 210, 0.24);
  font-size: 7px;
  letter-spacing: 0.2em;
  writing-mode: vertical-rl;
}

/* ------------------------------------------------------------------ */
/* Start screen                                                        */
/* ------------------------------------------------------------------ */

.start-screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  padding: max(24px, env(safe-area-inset-top)) max(38px, env(safe-area-inset-right)) max(22px, env(safe-area-inset-bottom)) max(38px, env(safe-area-inset-left));
  overflow: hidden;
  background:
    linear-gradient(90deg, rgba(6, 4, 5, 0.985) 0%, rgba(6, 4, 5, 0.94) 34%, rgba(6, 4, 5, 0.56) 63%, rgba(6, 4, 5, 0.76) 100%),
    radial-gradient(ellipse at 74% 42%, rgba(137, 31, 13, 0.2), transparent 44%),
    linear-gradient(180deg, rgba(6, 4, 5, 0.42), rgba(6, 4, 5, 0.18) 52%, rgba(6, 4, 5, 0.78));
  transition: opacity 380ms ease, visibility 380ms;
}

.start-screen::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 4.4%;
  width: 1px;
  background: linear-gradient(180deg, transparent 7%, rgba(255, 90, 22, 0.5) 30%, rgba(241, 230, 210, 0.08) 82%, transparent);
  opacity: 0.62;
}

.start-screen::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(180deg, transparent 0, transparent 4px, rgba(0, 0, 0, 0.13) 5px);
  opacity: 0.24;
  mix-blend-mode: multiply;
}

.start-screen.is-gone {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.start-grain {
  position: absolute;
  inset: 0;
  opacity: 0.12;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.45'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

.start-topline {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  color: rgba(241, 230, 210, 0.38);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.19em;
}

.signal { display: flex; align-items: center; gap: 7px; color: rgba(255, 133, 55, 0.72); }

.signal i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--ember);
  box-shadow: 0 0 10px var(--ember);
  animation: signal-pulse 1.6s ease-in-out infinite;
}

@keyframes signal-pulse { 50% { opacity: 0.3; } }

.start-layout {
  position: relative;
  z-index: 2;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8vw;
  width: 100%;
  max-width: 1360px;
  margin: 0 auto;
  padding: 1.5vh 0 3vh;
}

.start-copy { width: min(680px, 64vw); }

.start-kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 16px;
  color: var(--ember);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.24em;
}

.start-kicker::before {
  content: "";
  width: 36px;
  height: 1px;
  background: var(--ember);
  box-shadow: 0 0 8px rgba(255, 90, 22, 0.7);
}

.logo {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  margin: 0;
  color: var(--bone);
  font-family: var(--display);
  font-size: clamp(74px, 10.8vw, 168px);
  font-weight: 900;
  line-height: 0.7;
  letter-spacing: -0.085em;
  text-transform: uppercase;
  filter: drop-shadow(0 7px 0 rgba(21, 5, 4, 0.75));
}

.logo-hell { position: relative; z-index: 2; }

.logo-fire {
  position: relative;
  z-index: 1;
  color: transparent;
  background: linear-gradient(178deg, #ffd37a 2%, #ff7c24 38%, #d83810 68%, #7d160b 100%);
  -webkit-background-clip: text;
  background-clip: text;
  text-shadow: 0 0 38px rgba(255, 67, 14, 0.18);
}

.logo em {
  position: relative;
  z-index: 3;
  flex-basis: 100%;
  margin-top: 0.14em;
  padding-left: 0.07em;
  color: transparent;
  -webkit-text-stroke: 1.5px rgba(241, 230, 210, 0.76);
  font-family: var(--body);
  font-size: 0.25em;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.53em;
  line-height: 1;
  text-shadow: none;
}

.start-deck {
  max-width: 490px;
  margin: 30px 0 0;
  color: rgba(241, 230, 210, 0.66);
  font-size: 14px;
  line-height: 1.65;
  letter-spacing: 0.015em;
}

.start-actions {
  display: flex;
  align-items: center;
  gap: clamp(24px, 4vw, 58px);
  margin-top: 31px;
}

.start-button {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 42px;
  min-width: 214px;
  height: 64px;
  padding: 0 25px 0 31px;
  overflow: hidden;
  color: #170906;
  border: 0;
  background: linear-gradient(100deg, #ffc253 0%, #ff7b1e 36%, #f14b0d 78%, #b72b0b 100%);
  box-shadow: 0 0 38px rgba(255, 73, 13, 0.25), inset 0 1px 0 rgba(255, 239, 190, 0.7);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 15px), calc(100% - 15px) 100%, 0 100%);
  cursor: pointer;
  transition: filter 140ms ease, transform 140ms ease;
}

.start-button::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(105deg, transparent 30%, rgba(255, 255, 255, 0.34) 45%, transparent 60%);
  transform: translateX(-120%);
  transition: transform 500ms ease;
}

.start-button:hover { filter: brightness(1.09); transform: translateY(-1px); }
.start-button:hover::before { transform: translateX(120%); }
.start-button:active { transform: translateY(1px) scale(0.99); }

.start-button-label {
  position: relative;
  z-index: 1;
  font-family: var(--display);
  font-size: 22px;
  letter-spacing: 0.06em;
}

.start-button-arrow {
  position: relative;
  z-index: 1;
  font-family: var(--body);
  font-size: 25px;
  line-height: 1;
  transition: transform 160ms ease;
}

.start-button:hover .start-button-arrow { transform: translateX(4px); }

.control-grid {
  display: grid;
  grid-template-columns: repeat(2, auto);
  gap: 9px 23px;
  font-family: var(--mono);
}

.control-grid div { display: flex; align-items: center; gap: 8px; }

.control-grid kbd {
  min-width: 31px;
  padding: 3px 5px;
  color: rgba(241, 230, 210, 0.67);
  border: 1px solid rgba(241, 230, 210, 0.17);
  background: rgba(241, 230, 210, 0.035);
  font-family: var(--mono);
  font-size: 7px;
  text-align: center;
}

.control-grid span {
  color: rgba(241, 230, 210, 0.3);
  font-size: 7px;
  letter-spacing: 0.14em;
}

.start-brief {
  position: relative;
  width: 250px;
  flex: none;
  padding: 18px 20px 20px;
  color: rgba(241, 230, 210, 0.58);
  border: 1px solid rgba(241, 230, 210, 0.14);
  background: linear-gradient(150deg, rgba(24, 12, 12, 0.66), rgba(8, 5, 6, 0.42));
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
  backdrop-filter: blur(5px);
}

.brief-stamp {
  display: inline-block;
  padding: 3px 7px;
  color: var(--ember);
  border: 1px solid rgba(255, 90, 22, 0.35);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.18em;
}

.brief-art {
  position: relative;
  height: 142px;
  margin: 13px 0 9px;
  overflow: hidden;
  border-top: 1px solid rgba(241, 230, 210, 0.09);
  border-bottom: 1px solid rgba(241, 230, 210, 0.09);
}

.brief-number {
  position: absolute;
  right: -8px;
  bottom: -22px;
  color: transparent;
  -webkit-text-stroke: 1px rgba(255, 90, 22, 0.22);
  font-family: var(--display);
  font-size: 116px;
  line-height: 1;
  letter-spacing: -0.1em;
}

.sigil {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 106px;
  height: 106px;
  transform: translate(-50%, -50%) rotate(45deg);
  border: 1px solid rgba(255, 90, 22, 0.3);
