    speckle(g, 64, 64, 1901, 110, ['rgba(0,0,0,0.28)', 'rgba(210,181,145,0.06)', 'rgba(108,37,20,0.14)'], 1, 2);

    g.save();
    g.strokeStyle = 'rgba(255, 81, 18, 0.52)';
