renderProjectile(item, game) {
  const p = item.data;
  const H = this.H;
  const z = 0.52;
  const screenY = H * 0.5 + (EYE - z) * H / item.ty;
  const radius = Math.min(H * 0.075, Math.max(1.2, (H / item.ty) * 0.105));
  const ctx = this.ctx;
  const hot = p.hostile ? ['rgba(255, 235, 150, 1)', 'rgba(255, 92, 17, 0.9)', 'rgba(255, 41, 6, 0)'] : ['rgba(255, 255, 223, 1)', 'rgba(255, 173, 45, 0.9)', 'rgba(255, 74, 12, 0)'];

  // Fire trail.
  if (p.trail && p.trail.length > 1) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.lineCap = 'round';
    const dirX = Math.cos(game.player.angle);
    const dirY = Math.sin(game.player.angle);
    const planeX = -dirY * PLANE;
    const planeY = dirX * PLANE;
    const invDet = 1 / (planeX * dirY - dirX * planeY);
    for (let i = 0; i < p.trail.length - 1; i++) {
      const dx1 = p.trail[i].x - game.player.x;
      const dy1 = p.trail[i].y - game.player.y;
      const tx = invDet * (dirY * dx1 - dirX * dy1);
      const ty = invDet * (-planeY * dx1 + planeX * dy1);
      if (ty <= 0.1) continue;
      const sx = (this.W * 0.5) * (1 + tx / ty);
      const sy = H * 0.5 + (EYE - z) * H / ty;
      if (i === 0) {
        ctx.beginPath();
        ctx.moveTo(sx, sy);
      } else {
        ctx.lineTo(sx, sy);
      }
    }
    ctx.strokeStyle = p.hostile ? 'rgba(255, 71, 12, 0.5)' : 'rgba(255, 196, 72, 0.48)';
    ctx.lineWidth = Math.max(1, radius * 0.9);
    ctx.stroke();
    ctx.restore();
  }

  this.screenGlow(item.screenX, screenY, Math.min(H * 0.14, radius * 3.8), hot[0], hot[2]);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = hot[1];
  ctx.beginPath();
  ctx.arc(item.screenX, screenY, radius, 0, TAU);
  ctx.fill();
  ctx.fillStyle = hot[0];
  ctx.beginPath();
  ctx.arc(item.screenX, screenY, radius * 0.46, 0, TAU);
  ctx.fill();
  ctx.restore();
}

renderParticles(game, px, py, dirX, dirY, planeX, planeY, invDet) {
  const H = this.H;
  const ctx = this.ctx;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const p of game.particles) {
    if (p.life <= 0) continue;
    const dx = p.x - px;
    const dy = p.y - py;
    const tx = invDet * (dirY * dx - dirX * dy);
    const ty = invDet * (-planeY * dx + planeX * dy);
    if (ty <= 0.1) continue;
    const sx = (this.W * 0.5) * (1 + tx / ty);
    const sy = H * 0.5 + (EYE - p.z) * H / ty;
    const radius = Math.max(0.5, (H / ty) * p.size * (0.5 + p.life / p.maxLife * 0.5));
    if (sx < -radius || sx > this.W + radius) continue;
    const alpha = clamp(p.life / p.maxLife, 0, 1);
    ctx.globalAlpha = alpha * 0.85;

