  await page.locator('#start-button').click(); await page.waitForTimeout(600);
  const result = await page.evaluate(()=>new Promise(res=>{
    const r = window.__hellfire.renderer;
    const names = ['renderFloorAndCeiling','renderWalls','collectRenderables','renderParticles','renderWeapon','drawMinimap'];
    const times = {}; const counts={};
    for (const name of names) {
      const orig = r[name].bind(r);
      times[name]=0; counts[name]=0;
      r[name]=(...args)=>{const t=performance.now(); const out=orig(...args); times[name]+=performance.now()-t; counts[name]++; return out;};
    }
    // also time enemy, brazier, projectile
    for (const name of ['renderEnemy','renderBrazier','renderProjectile','renderPickup']) {
      const orig=r[name].bind(r); times[name]=0; counts[name]=0;
      r[name]=(...args)=>{const t=performance.now(); const out=orig(...args); times[name]+=performance.now()-t; counts[name]++; return out;};
    }
    const start=performance.now(); let n=0;
    function f(t){n++; if(t-start<3000) requestAnimationFrame(f); else {
      const seconds=(t-start)/1000;
      for(const k in times) times[k]=+(times[k]/n).toFixed(3);
      res({fps:+(n/seconds).toFixed(1), msPerFrame:times, calls:counts, W:r.W,H:r.H});
    }}
    requestAnimationFrame(f);
  }));
  console.log(result);
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
